class Node:
    """A node used in the skip list that holds a key, value, and pointers to forward nodes."""
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.forward = []

class LRUCache:
    """
    A least recently used (LRU) cache structure.
    It uses a skip list to achieve O(1) average time complexity for get and put operations.
    The skip list maintains an ordered structure for fast access while allowing for eviction of 
    the least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head = Node(0, 0)
        self.head.forward = [None] * (capacity + 1)
        self.size = 0

    def _insert_node(self, node: Node) -> None:
        """Insert a node in the skip list."""
        current = self.head
        for i in range(self.size, -1, -1):
            while current.forward[i] and current.forward[i].key < node.key:
                current = current.forward[i]
            if i == 0:  # Only for the last level
                node.forward.append(current.forward[i])
                current.forward[i] = node

    def _remove_node(self, key: int) -> None:
        """Remove a node with a specific key from the skip list."""
        current = self.head
        for i in range(self.size, -1, -1):
            while current.forward[i] and current.forward[i].key < key:
                current = current.forward[i]
            if current.forward[i] and current.forward[i].key == key:
                current.forward[i] = current.forward[i].forward[i]

    def get(self, key: int) -> int:
        """Return the value of the key if the key exists, otherwise return -1."""
        node = self.cache.get(key)
        if node:
            return node.value
        return -1

    def put(self, key: int, value: int) -> None:
        """Add a key-value pair to the cache."""
        if key in self.cache:
            node = self.cache[key]
            node.value = value
        else:
            if self.size < self.capacity:
                new_node = Node(key, value)
                self.cache[key] = new_node
                self._insert_node(new_node)
                self.size += 1
            else:
                # Remove least recently used (first node in the skip list)
                lru_key = self.head.forward[0].key
                self._remove_node(lru_key)
                del self.cache[lru_key]
                new_node = Node(key, value)
                self.cache[key] = new_node
                self._insert_node(new_node)
